with cleaned as (select id, order_id, carrier, cost, status, last_day(shipped_date) as shipped_date_month_end, substring(carrier, 1, 4) as carrier_prefix, coalesce(carrier, 'DIRECT') as carrier_clean from shipments where delivered_date >= to_date('2023-05-14') and cost between 59 and 81) select id, order_id, cost, carrier_prefix, carrier_clean, round(cost / sum(cost) over (partition by carrier, order_id), 4) as cost_share, lag(cost, 2) over (partition by status order by shipped_date_month_end, id) as prev_cost from cleaned;
